import{_ as i,o as e,c as t,a2 as s}from"./chunks/framework.z3u3TMv0.js";const k=JSON.parse('{"title":"安裝 A1111（SD WebUI）","description":"安裝 AUTOMATIC1111 Stable Diffusion WebUI，開啟 --api 與局域網，供 MiniTavern 生圖連接。","frontmatter":{"title":"安裝 A1111（SD WebUI）","description":"安裝 AUTOMATIC1111 Stable Diffusion WebUI，開啟 --api 與局域網，供 MiniTavern 生圖連接。","head":[["meta",{"name":"keywords","content":"酒館,AI酒館,Ai酒館,迷你酒館,超迷你酒館,MiniTavern,AI夥伴,AI朋友,Ai本地聊天,Silly Tavern,SillyTavern,手機玩Silly Tavern,Silly Tavern手機版,Silly Tavern安卓,Silly Tavern蘋果,AI角色扮演,角色卡,角色扮演,AI聊天,手機AI,離線AI,AI劇情,本地大模型,本地模型,Ollama,LM Studio,世界書,正則,BYOK,使用手冊,教學,character card,AI roleplay,AI companion"}],["meta",{"property":"og:title","content":"安裝 A1111（SD WebUI） · MiniTavern Docs"}],["meta",{"property":"og:description","content":"安裝 AUTOMATIC1111 Stable Diffusion WebUI，開啟 --api 與局域網，供 MiniTavern 生圖連接。"}],["meta",{"property":"og:url","content":"https://minitavern.github.io/ultra_guides/zh-TW/local/image-gen/a1111"}],["link",{"rel":"canonical","href":"https://minitavern.github.io/ultra_guides/zh-TW/local/image-gen/a1111"}]]},"headers":[],"relativePath":"zh-TW/local/image-gen/a1111.md","filePath":"zh-TW/local/image-gen/a1111.md","lastUpdated":1787224147000}'),n={name:"zh-TW/local/image-gen/a1111.md"};function l(h,a,o,p,d,r){return e(),t("div",null,[...a[0]||(a[0]=[s(`<h1 id="安裝-a1111-sd-webui" tabindex="-1">安裝 A1111（SD WebUI） <a class="header-anchor" href="#安裝-a1111-sd-webui" aria-label="Permalink to &quot;安裝 A1111（SD WebUI）&quot;">​</a></h1><p>AUTOMATIC1111（常稱 <strong>A1111 / SD WebUI</strong>）提供瀏覽器界面與 REST API（<code>/sdapi/v1/txt2img</code>）。<br> MiniTavern 的 <strong>A1111(SD WebUI)</strong> 平臺即對接此 API；<strong>SD.Next</strong> 等同協議亦可嘗試。</p><p>官方倉庫：<a href="https://github.com/AUTOMATIC1111/stable-diffusion-webui" target="_blank" rel="noreferrer">AUTOMATIC1111/stable-diffusion-webui</a></p><h2 id="硬件建議" tabindex="-1">硬件建議 <a class="header-anchor" href="#硬件建議" aria-label="Permalink to &quot;硬件建議&quot;">​</a></h2><table tabindex="0"><thead><tr><th>顯存</th><th>建議</th></tr></thead><tbody><tr><td>6GB</td><td>SD 1.5、較小分辨率</td></tr><tr><td>8GB+</td><td>SDXL 更穩妥</td></tr><tr><td>僅 CPU</td><td>可跑但極慢，僅作驗證</td></tr></tbody></table><h2 id="windows-推薦入門" tabindex="-1">Windows（推薦入門） <a class="header-anchor" href="#windows-推薦入門" aria-label="Permalink to &quot;Windows（推薦入門）&quot;">​</a></h2><h3 id="_1-安裝依賴" tabindex="-1">1. 安裝依賴 <a class="header-anchor" href="#_1-安裝依賴" aria-label="Permalink to &quot;1. 安裝依賴&quot;">​</a></h3><ol><li>安裝 <a href="https://git-scm.com/download/win" target="_blank" rel="noreferrer">Git for Windows</a>。</li><li>安裝 <a href="https://www.python.org/downloads/" target="_blank" rel="noreferrer">Python 3.10.x</a>（安裝時勾選 <strong>Add python.exe to PATH</strong>）。</li><li>建議已安裝較新的 <strong>NVIDIA 驅動</strong>（有 NVIDIA 顯卡時）。</li></ol><h3 id="_2-下載-webui" tabindex="-1">2. 下載 WebUI <a class="header-anchor" href="#_2-下載-webui" aria-label="Permalink to &quot;2. 下載 WebUI&quot;">​</a></h3><p>在合適目錄（如 <code>D:\\AI</code>）打開 PowerShell：</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">git clone https:</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">//</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">github.com</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">AUTOMATIC1111</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">stable</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">diffusion</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">webui.git</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">cd stable</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">diffusion</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">webui</span></span></code></pre></div><h3 id="_3-首次啟動" tabindex="-1">3. 首次啟動 <a class="header-anchor" href="#_3-首次啟動" aria-label="Permalink to &quot;3. 首次啟動&quot;">​</a></h3><p>雙擊或在終端運行：</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.\\</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">webui-user.bat</span></span></code></pre></div><p>首次會自動下載依賴與基礎組件，耗時較長。完成後瀏覽器一般打開：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>http://127.0.0.1:7860</span></span></code></pre></div><h3 id="_4-開啟-api-局域網-連手機必做" tabindex="-1">4. 開啟 API + 局域網（連手機必做） <a class="header-anchor" href="#_4-開啟-api-局域網-連手機必做" aria-label="Permalink to &quot;4. 開啟 API + 局域網（連手機必做）&quot;">​</a></h3><p>編輯同目錄下的 <code>webui-user.bat</code>，找到 <code>COMMANDLINE_ARGS</code> 一行，改為例如：</p><div class="language-bat vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bat</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">set</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> COMMANDLINE_ARGS</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">--api --listen</span></span></code></pre></div><p>說明：</p><table tabindex="0"><thead><tr><th>參數</th><th>作用</th></tr></thead><tbody><tr><td><code>--api</code></td><td>開啟 <code>/sdapi/v1/*</code>（<strong>MiniTavern 必需</strong>）</td></tr><tr><td><code>--listen</code></td><td>監聽 <code>0.0.0.0</code>，允許局域網設備訪問</td></tr><tr><td><code>--port 7860</code></td><td>可選；改端口時 App 裡同步改</td></tr></tbody></table><p>保存後重新運行 <code>webui-user.bat</code>。</p><p>可選：<code>--api-auth 用戶名:密碼</code> 給 API 加鑑權；若啟用，在 App 生圖連接的 API Key / 鑑權字段按實現要求填寫（以當前 App 文案為準）。</p><h3 id="_5-驗證-api" tabindex="-1">5. 驗證 API <a class="header-anchor" href="#_5-驗證-api" aria-label="Permalink to &quot;5. 驗證 API&quot;">​</a></h3><p>本機瀏覽器打開：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>http://127.0.0.1:7860/docs</span></span></code></pre></div><p>能看到 Swagger 文檔即 API 已開。局域網驗證（把 IP 換成電腦 IP）：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>http://192.168.x.x:7860/docs</span></span></code></pre></div><h2 id="macos-linux-摘要" tabindex="-1">macOS / Linux 摘要 <a class="header-anchor" href="#macos-linux-摘要" aria-label="Permalink to &quot;macOS / Linux 摘要&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/AUTOMATIC1111/stable-diffusion-webui.git</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> stable-diffusion-webui</span></span></code></pre></div><p>編輯 <code>webui-user.sh</code>，設置：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> COMMANDLINE_ARGS</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;--api --listen&quot;</span></span></code></pre></div><p>再執行 <code>./webui.sh</code>。Apple Silicon 可用，速度通常慢於同級 NVIDIA。</p><h2 id="下載模型-checkpoint" tabindex="-1">下載模型（Checkpoint） <a class="header-anchor" href="#下載模型-checkpoint" aria-label="Permalink to &quot;下載模型（Checkpoint）&quot;">​</a></h2><ol><li>從 <a href="https://civitai.com/" target="_blank" rel="noreferrer">Civitai</a> 或 <a href="https://huggingface.co/" target="_blank" rel="noreferrer">Hugging Face</a> 下載 <code>.safetensors</code> 模型。</li><li>放入：</li></ol><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>stable-diffusion-webui/models/Stable-diffusion/</span></span></code></pre></div><ol start="3"><li>在 WebUI 左上角刷新並選擇模型；或重啟 WebUI。</li></ol><p>入門可先下一款 SD 1.5 或 SDXL 通用模型，確認能在 WebUI 裡手動出圖，再連 App。</p><h2 id="防火牆" tabindex="-1">防火牆 <a class="header-anchor" href="#防火牆" aria-label="Permalink to &quot;防火牆&quot;">​</a></h2><p>Windows：首次監聽時允許專用網絡訪問，或在防火牆中放行端口 <strong>7860</strong>。<br> 手機必須與電腦同一局域網；訪客 Wi‑Fi 常隔離客戶端。</p><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li><a href="./connect-app">在 MiniTavern 中配置</a>（平臺選 A1111，Base URL 填電腦局域網地址）</li><li>對照：<a href="./index">生圖模型部署</a> · App 內 <a href="/ultra_guides/zh-TW/manual/model-link">模型連接 · 生圖</a></li></ul>`,42)])])}const b=i(n,[["render",l]]);export{k as __pageData,b as default};
